import zipfile,json,re,collections
p='/mnt/data/training 3.zip'
with zipfile.ZipFile(p) as z:
 files=[n for n in z.namelist() if n.startswith('training/chatgpt_audit/corpus/') and n.endswith('.ndjson')]
 print('NDJSON total',len(files))
 for n in files[:3]:
  ls=z.read(n).decode().splitlines();print('\nFILE',n,'LINES',len(ls));print('SAMPLE',ls[0][:1200]);
  if len(ls)>1:print('SAMPLE 2',ls[1][:500]);
 matches=[]
 for n in files:
  ls=z.read(n).decode('utf-8').splitlines();count=0
  for i,ln in enumerate(ls):
   if re.search(r'doxx?(?:ing|ed)?|privacy clause|doxing clause|the clause',ln,re.I):
    try:obj=json.loads(ln);s=str(obj.get('content',obj.get('text',obj.get('body',''))))
    except Exception:s=ln
    if re.search(r'dox',s,re.I):
     count+=1;matches.append((n,i,s[:850]))
  if count:print('DOX',n.rsplit('/',1)[-1],count)
 print('MATCHES:',len(matches))
 for n,i,s in matches[:55]:print('\n',n.rsplit('/',1)[-1],i+1,'::',s.replace('\n',' ')[:700])
