 for n in z.namelist():
  if n.startswith('training/chatgpt_audit/corpus/Draft research prompt') and n.endswith('.ndjson'):
   data=z.read(n);rows=[json.loads(l) for l in data.decode().split('\n') if l.strip()];print('\n\n---',os.path.basename(n),'ROWS',len(rows),'sha',hashlib.sha256(data).hexdigest()[:12]);
